    std::uint64_t *aWUSaltB = pDomainSaltSet->mWandererUpdate.mSaltB;
    std::uint64_t *aWUSaltC = pDomainSaltSet->mWandererUpdate.mSaltC;
    std::uint64_t *aWUSaltD = pDomainSaltSet->mWandererUpdate.mSaltD;
    std::uint64_t *aWUSaltE = pDomainSaltSet->mWandererUpdate.mSaltE;
    std::uint64_t *aWUSaltF = pDomainSaltSet->mWandererUpdate.mSaltF;
